(()=>{const message=document.querySelector('#shop-message');function render(){document.querySelectorAll('[data-buy]').forEach(button=>{const owned=PixelEconomy.owns(button.dataset.buy);button.disabled=owned;button.textContent=owned?'Owned ✓':'Buy for '+button.dataset.cost+' points';button.classList.toggle('is-owned',owned)})}document.querySelectorAll('[data-buy]').forEach(button=>button.addEventListener('click',()=>{const result=PixelEconomy.buy(button.dataset.buy,button.dataset.cost);if(result.ok)message.textContent='Upgrade purchased. Its effect is now active in that game.';else if(result.reason==='points')message.textContent='Keep playing to earn enough points for this upgrade.';else message.textContent='You already own this upgrade.';render()}));window.addEventListener('pixelparty:wallet',render);render()})();
